#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import json
import re
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
HTML_FILE = HERE / "kpi_anac.html"
DATA_FILE = HERE.parent / "04 - json" / "kpi_report.json"
LABELS_FILE = HERE / "labels.yaml"


def escape_json(s: str) -> str:
    return s.replace("</", "<\\/").replace("<!--", "<\\u003c!--")


def embed(html: str, tag_id: str, content: str) -> str:
    pattern = re.compile(
        r'(<script type="application/json" id="' + re.escape(tag_id) + r'">\r?\n).*?(\r?\n</script>)',
        re.DOTALL,
    )
    if not pattern.search(html):
        raise RuntimeError(f"Marker non trovato per id='{tag_id}' in kpi_anac.html")
    return pattern.sub(lambda m: m.group(1) + content + m.group(2), html)


def main():
    if not DATA_FILE.exists():
        raise SystemExit(f"File JSON non trovato: {DATA_FILE}")

    data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    labels = yaml.safe_load(LABELS_FILE.read_text(encoding="utf-8"))

    data_content = escape_json(json.dumps(data, ensure_ascii=False, indent=2))
    labels_content = escape_json(json.dumps(labels, ensure_ascii=False, indent=2))

    html = HTML_FILE.read_text(encoding="utf-8")
    html = embed(html, "embedded-data", data_content)
    html = embed(html, "embedded-labels", labels_content)
    HTML_FILE.write_text(html, encoding="utf-8")

    print("Snapshot incorporato aggiornato in kpi_anac.html")
    print(f"  dati   : {DATA_FILE.name} ({len(data_content)/1024:.0f} KB)")
    print(f"  labels : {LABELS_FILE.name} ({len(labels_content)/1024:.0f} KB)")


if __name__ == "__main__":
    main()

