ssh -o ConnectTimeout=30 mxmap.it@51.158.36.151 'bash -s' <<'REMOTE' 2>&1 | tail -30
cd ~/analisi-spesa-ict && mkdir -p lavoro/wayback
F=lavoro/wayback/cdx-ocds.json
curl -sS --max-time 150 "https://web.archive.org/cdx/search/cdx?url=dati.anticorruzione.it%2Fopendata%2Fdownload%2Fdataset%2Focds%2Ffilesystem%2Fbulk%2F*&output=json&filter=statuscode:200&limit=4000" -o "$F" -w "http %{http_code}  byte %{size_download}\n"
python3 - "$F" <<'PY'
import json,sys,collections,re
rows=json.load(open(sys.argv[1]))
idx={k:i for i,k in enumerate(rows[0])}
mesi=collections.defaultdict(set)
for r in rows[1:]:
    m=re.search(r'/bulk/(\d{4})/(\d{2})\.json', r[idx['original']])
    if m: mesi[f"{m.group(1)}/{m.group(2)}"].add((r[idx['timestamp']][:8], int(r[idx['length']])))
print(f"righe: {len(rows)-1}   mesi distinti: {len(mesi)}")
print("per anno:", dict(sorted(collections.Counter(k[:4] for k in mesi).items())))
recenti={k:v for k,v in mesi.items() if k>='2024/01'}
print(f"\nmesi dal 2024: {len(recenti)}")
for k in sorted(recenti):
    for ts,ln in sorted(recenti[k]): print(f"  {k}  {ts}  {ln/1e6:.1f} MB")
print("\nmesi catturati piu volte con dimensioni diverse (instabilita del file):")
n=0
for k in sorted(mesi):
    v=sorted(mesi[k])
    if len({ln for _,ln in v})>1:
        n+=1
        if n<=5: print(f"  {k}: "+", ".join(f"{ts}={ln/1e6:.1f}MB" for ts,ln in v))
print(f"  totale mesi instabili: {n} su {len(mesi)}")
PY
REMOTE

