.beta-tip { position:absolute; top:calc(100% + 9px); left:-4px; width:300px; max-width:calc(100vw - 28px); background:#fff; color:#222; border:1px solid #d0d7de; border-radius:8px; box-shadow:0 10px 28px rgba(0,0,0,.22); padding:12px 14px; font-size:12.5px; font-weight:400; line-height:1.55; letter-spacing:normal; white-space:normal; z-index:3000; opacity:0; visibility:hidden; transform:translateY(-4px); transition:opacity .15s, transform .15s; }
.beta-wrap:hover .beta-tip, .beta-wrap:focus-within .beta-tip, .beta-wrap.open .beta-tip { opacity:1; visibility:visible; transform:translateY(0); }
.beta-tip a { color:#0066CC; font-weight:600; text-decoration:none; }
.beta-tip a:hover { text-decoration:underline; }
.beta-tip .arr { position:absolute; top:-6px; left:14px; width:11px; height:11px; background:#fff; border-left:1px solid #d0d7de; border-top:1px solid #d0d7de; transform:rotate(45deg); }
/* mobile: riquadro ancorato ai bordi schermo, mai fuori viewport */
@media (max-width:560px){
  .beta-tip { position:fixed; top:48px; left:10px; right:10px; width:auto; max-width:none; font-size:13px; }
  .beta-tip .arr { display:none; }
}
.updated { font-size: 11px; color: #888; }
.toggle-info {
  background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3);
  color: #ccc; font-size: 13px; font-weight: 500; padding: 5px 14px; border-radius: 4px; cursor: pointer;
  white-space: nowrap;
}
.toggle-info:hover { background: rgba(255,255,255,0.25); color: #fff; }
.gateway-icon { background: none !important; border: none !important; }
.dominance-label { background: none !important; border: none !important; text-align: center; }

#info-bar, #stats-bar {
  background: #f8f9fb; border-bottom: 1px solid #e2e4e8; overflow: hidden; flex-shrink: 0;
  max-height: 2000px; padding: 16px 20px;
}
#info-bar:not(.collapsed), #stats-bar:not(.collapsed) { max-height: 80vh; overflow-y: auto; -webkit-overflow-scrolling: touch; }
#info-bar.collapsed, #stats-bar.collapsed { max-height: 0; padding-top: 0; padding-bottom: 0; }
.info-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}
.info-card h3 { font-size: 13px; font-weight: 600; margin-bottom: 2px; color: #1a1a2e; }
.info-card p { font-size: 12px; color: #444; line-height: 1.4; margin: 0; }
.info-card a { color: #2563eb; text-decoration: none; }
.info-card a:hover { text-decoration: underline; }
.info-title { display: none; font-size: 16px; font-weight: 600; color: #1a1a2e; margin-bottom: 12px; }

input.content:
/* Stile del sito analisi-spesa-ict: branding di mxmap.it / Osservatorio Nazionale Sovranità Digitale */
:root {
  --notte: #1a1a2e;
  --blu: #0066CC;
  --blu-scuro: #003DA5;
  --beta: #E8A33D;
  --it: #2E7D32;
  --ue: #003DA5;
  --extra-ue: #CE1126;
  --ignoto: #607d8b;
  --fondo: #f8f9fb;
  --bordo: #e2e4e8;
  --testo: #222;
  --tenue: #555;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; color: var(--testo); background: #fff; line-height: 1.6; }
a { color: var(--blu); text-decoration: none; }
a:hover { text-decoration: underline; }
code { font-family: ui-monospace, Menlo, monospace; font-size: .9em; background: #f0f2f5; padding: 1px 5px; border-radius: 4px; }

/* testata, come mxmap.it */
#header {
  background: var(--notte); color: #fff; min-height: 44px; padding: 6px 16px;
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  position: sticky; top: 0; z-index: 10;
}
.header-left { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand { font-size: 15px; font-weight: 700; margin: 0; line-height: 1.15; color: #fff; }
.brand span { color: #6BA3D6; }
.beta-badge { background: var(--beta); color: #fff; font-size: 10px; font-weight: 700; letter-spacing: .5px; padding: 2px 6px; border-radius: 4px; }
.separator { color: #555; }
.tagline { color: #a0a0b0; font-size: 13px; }
nav.menu { display: flex; gap: 6px; flex-wrap: wrap; }
nav.menu a {
  background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.25); color: #ddd;
  font-size: 13px; padding: 4px 11px; border-radius: 4px;
}
nav.menu a:hover { background: rgba(255,255,255,.25); color: #fff; text-decoration: none; }
@media (max-width: 640px) { .tagline, .separator { display: none; } }

/* contenuto */
main { max-width: 980px; margin: 0 auto; padding: 28px 18px 60px; }
.hero { border-left: 4px solid var(--blu); padding: 6px 0 6px 18px; margin-bottom: 30px; }
.hero h2 { font-size: 28px; line-height: 1.2; margin: 0 0 10px; color: var(--notte); }
.hero p { font-size: 17px; color: var(--tenue); margin: 0; }
h2 { color: var(--notte); }
h3 { color: var(--notte); margin-bottom: 6px; }
section { margin: 40px 0; scroll-margin-top: 60px; }

.obiettivi { counter-reset: ob; display: grid; gap: 14px; }
.obiettivo {
  border: 1px solid var(--bordo); border-radius: 10px; padding: 16px 18px 14px; background: #fff;
  position: relative;
}
.obiettivo.finale { border: 2px solid var(--blu); background: #f3f8fe; }
.obiettivo h3 { margin-top: 0; display: flex; gap: 10px; align-items: baseline; }
.num {
  flex: 0 0 auto; background: var(--notte); color: #fff; width: 28px; height: 28px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700;
}
.finale .num { background: var(--blu); }
.stato { font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 10px; white-space: nowrap; margin-left: auto; }
.stato.in-corso { background: #fff3e0; color: #a35f00; }
.stato.avviato  { background: #e3f2fd; color: var(--blu-scuro); }
.stato.da-fare  { background: #eceff1; color: #455a64; }
.stato.fatto    { background: #e8f5e9; color: var(--it); }
.obiettivo p { margin: 6px 0; }
.risultati { margin: 10px 0 0; padding: 10px 14px; background: var(--fondo); border-radius: 8px; font-size: 14px; }
.risultati strong { display: block; font-size: 12px; text-transform: uppercase; letter-spacing: .4px; color: var(--tenue); margin-bottom: 4px; }
.risultati ul { margin: 0; padding-left: 18px; }
.vuoto { color: #888; font-style: italic; }

.cifre { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin: 16px 0; }
.cifra { background: var(--fondo); border: 1px solid var(--bordo); border-radius: 8px; padding: 12px 14px; }
.cifra b { display: block; font-size: 24px; color: var(--notte); line-height: 1.1; }
.cifra span { font-size: 13px; color: var(--tenue); }

table { border-collapse: collapse; width: 100%; font-size: 14px; margin: 12px 0; }
th, td { border-bottom: 1px solid var(--bordo); padding: 7px 8px; text-align: left; vertical-align: top; }
th { background: var(--fondo); font-weight: 600; }
.tabella { overflow-x: auto; }

.bucket { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 4px; vertical-align: middle; }
.nota { font-size: 14px; color: var(--tenue); border-left: 3px solid var(--beta); padding: 4px 0 4px 12px; }

/* rendiconti */
article.rendiconto { font-size: 15.5px; }
article.rendiconto h1 { color: var(--notte); font-size: 26px; line-height: 1.25; }
article.rendiconto h2 { border-bottom: 1px solid var(--bordo); padding-bottom: 4px; margin-top: 34px; }
article.rendiconto table { font-size: 13.5px; }
.fonte-rendiconto { font-size: 13px; color: var(--tenue); background: var(--fondo); padding: 8px 12px; border-radius: 6px; }

footer { border-top: 1px solid var(--bordo); background: var(--fondo); font-size: 13px; color: var(--tenue); }
footer div { max-width: 980px; margin: 0 auto; padding: 18px; }

