        { "@type": "PropertyValue", "name": "{{ if $isEN }}PA on EU providers (non-Italian){{ else }}PA su provider UE (non italiani){{ end }}", "value": {{ site.Data.kpi.sovereignty.eu_non_it.pct }}, "unitText": "PERCENT" },
        { "@type": "PropertyValue", "name": "{{ if $isEN }}PA bodies analysed{{ else }}Enti PA analizzati{{ end }}", "value": {{ site.Data.kpi.totals.n_entities }} }
