{{ define "main" }}
<section class="hero-custom">
  <div class="container-xxl">
    <div class="row">
      <div class="col-lg-9">
        <h1>{{ .Params.heroTitle | default .Title }}</h1>
        <p class="lead mb-0">{{ .Params.heroLead }}</p>
      </div>
    </div>
  </div>
</section>

<div class="container-xxl section-spacing">
  <div class="row justify-content-center">
    <div class="col-lg-9 article-content">
      {{ .Content }}
    </div>
  </div>
</div>

{{ with where site.RegularPages "Section" "rendiconti" }}
<section class="bg-section-alt section-spacing">
  <div class="container-xxl">
    <h2 class="mb-4">Ultimi rendiconti</h2>
    <div class="row g-4">
      {{ range first 3 . }}
      <div class="col-lg-4 col-md-6">
        <div class="card-wrapper">
          <div class="card card-bg rounded shadow-sm">
            <div class="card-body">
              <div class="category-top">
                <span class="category">{{ .Params.ente | default "Rendiconto" }}</span>
                <span class="data">{{ partial "date-it.html" .Date }}</span>
              </div>
              <h3 class="card-title h5"><a href="{{ .RelPermalink }}">{{ .Title }}</a></h3>
              <p class="card-text">{{ .Description | default (.Summary | plainify | truncate 180) }}</p>
            </div>
          </div>
        </div>
      </div>
      {{ end }}
    </div>
  </div>
</section>
{{ end }}

<style>
  .obiettivo { border: 1px solid #d9dadb; border-radius: .5rem; padding: 1.25rem 1.5rem; margin-bottom: 1rem; background: #fff; }
  .obiettivo.finale { border: 2px solid var(--bs-primary); background: #f2f7fc; }
  .obiettivo h3 { margin-top: 0 !important; display: flex; gap: .75rem; align-items: center; flex-wrap: wrap; font-size: 1.3rem; }
  .ob-num { flex: 0 0 auto; width: 2rem; height: 2rem; border-radius: 50%; background: #1a1a2e; color: #fff;
            display: inline-flex; align-items: center; justify-content: center; font-size: 1rem; font-weight: 700; }
  .finale .ob-num { background: var(--bs-primary); }
  .ob-stato { margin-left: auto; font-size: .75rem; font-weight: 600; padding: .15rem .6rem; border-radius: 1rem; }
  .ob-stato.in-corso { background: #fff3e0; color: #a35f00; }
  .ob-stato.avviato  { background: #e3f2fd; color: #003DA5; }
  .ob-stato.fatto    { background: #e8f5e9; color: #2E7D32; }
  .ob-stato.da-fare  { background: #eceff1; color: #455a64; }
  .ob-risultati { background: #f5f7f9; border-radius: .4rem; padding: .75rem 1rem; font-size: .95rem; margin-top: .75rem; }
  .ob-risultati p:first-child { font-size: .75rem; text-transform: uppercase; letter-spacing: .04em; color: #5c6f82; font-weight: 600; margin-bottom: .25rem; }
  .ob-risultati ul { margin-bottom: 0; }
  .bucket { display: inline-block; width: .7rem; height: .7rem; border-radius: 2px; margin: 0 .3rem 0 .6rem; vertical-align: middle; }
  .cifre { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: .75rem; margin: 1.25rem 0; }
  .cifra { background: #f2f7fc; border-left: 4px solid var(--bs-primary); border-radius: .4rem; padding: .8rem 1rem; }
  .cifra b { display: block; font-size: 1.6rem; color: #1a1a2e; line-height: 1.1; }
  .cifra span { font-size: .85rem; color: #5c6f82; }
</style>
{{ end }}

