# figli dei lotti Consip IaaS/PaaS per marca: quanti CIG derivati e importo (lente prodotto ereditata)
import csv,glob,io,zipfile,collections
D="archivio/mirror/dati.anticorruzione.it/opendata/download/dataset/"
padri={}
rows=[]
for y in ("2024","2025"):
  for z in sorted(glob.glob(D+f"cig-{y}/filesystem/cig_csv_*.zip")):
    zf=zipfile.ZipFile(z)
    for r in csv.DictReader(io.TextIOWrapper(zf.open(zf.namelist()[0]),encoding="utf-8-sig",errors="replace"),delimiter=";"):
      o=(r["oggetto_lotto"] or "").upper()
      if "CONSIP" in r["denominazione_amministrazione_appaltante"].upper() and ("IAAS" in o or "PAAS" in o or "CLOUD" in o): padri[r["cig"]]=o[:70]
      if r["cig_accordo_quadro"]: rows.append((r["cig_accordo_quadro"],float(r["importo_lotto"] or 0)))
print("lotti Consip cloud:",len(padri))
for k,v in padri.items(): print(" ",k,v)
c=collections.Counter(); s=collections.Counter()
for p,v in rows:
  if p in padri: c[p]+=1; s[p]+=v
print("derivati:")
for p in c: print(" ",padri[p][:50],c[p],round(s[p]/1e6,1),"M")
EOF' 2>&1 | head -60

