            "award": len(award), "award_con_fornitore": con_forn,
            "pct_award_con_fornitore": round(con_forn / len(award) * 100, 1) if award else None,
            "tabellari_aggiudicati_nel_mese": len(tab), "di_cui_in_ocds": len(tab & award),
