7:    -> {"via": "3-marchio", "provider": "Microsoft", "giurisdizione": "EXTRA-UE", "servizio": "cloud",
20:RX_AQ2746 = re.compile(r"2746|iaas\s*(e|/|-)?\s*paas\s*(2|ed\.?\s*2|edizione\s*2)\b", re.I)
21:RX_LOTTO = re.compile(r"\blott?o\s*n?\.?\s*(\d)\b", re.I)
22:RX_CLOUD = re.compile(r"\bcloud\b|\bsaas\b|\biaas\b|\bpaas\b|\bhosting\b|data\s*cent(er|re)|\bhousing\b", re.I)
23:# "servizi applicativi in ottica cloud" (AQ Consip) è sviluppo applicativo, non servizio cloud
