import csv,glob,collections
def carica(d):
  return {r["cig"]:r for f in sorted(glob.glob(d+"/[0-9]*.csv")) for r in csv.DictReader(open(f,encoding="utf-8"))}
a=carica("lavoro/v3-prima"); b=carica("lavoro/attribuzione")
ch=collections.Counter(); imp=collections.Counter(); es=collections.defaultdict(list)
for c in set(a)|set(b):
  x=a.get(c,{}); y=b.get(c,{})
  kx=(x.get("via","-")[:1],x.get("servizio","")); ky=(y.get("via","-")[:1],y.get("servizio",""))
  if kx!=ky or x.get("provider")!=y.get("provider"):
    k=(kx,ky); ch[k]+=1
    v=y or x
    if v.get("e_padre")!="1" and v.get("importo_da_verificare")!="1": imp[k]+=float(v.get("importo_lotto") or 0)
    if len(es[k])<2: es[k].append(v["testo"][:110])
for k,n in ch.most_common(): print(n, round(imp[k]/1e6,2), k, es[k])
print("tel totale", sum(n for k,n in ch.items() if k[1][1]=="telefonia"), round(sum(v for k,v in imp.items() if k[1][1]=="telefonia")/1e6,2))
EOF'

