schema.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

input.command:
mkdir -p tools/llm report/metodo/llm/lotti report/metodo/llm/esiti && cat > tools/llm/prepara_lotti.js <<'EOF'
// Divide il campione (611 contratti) in lotti da 20 per la classificazione assistita da modello linguistico + ricerca web.
// Ingresso: campione cieco + proposta v3.1. Uscita: report/metodo/llm/lotti/lotto-NN.jsonl
const fs = require("fs"), path = require("path");
const R = path.resolve(__dirname, "../..");
function csv(f) {
  const t = fs.readFileSync(path.join(R, f), "utf8"), rows = []; let row = [], cell = "", q = false;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (q) { if (c === '"') { if (t[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; }
    else if (c === '"') q = true; else if (c === ",") { row.push(cell); cell = ""; }
    else if (c === "\n") { row.push(cell.replace(/\r$/, "")); rows.push(row); row = []; cell = ""; } else cell += c;
  }
  if (cell || row.length) { row.push(cell); rows.push(row); }
  const h = rows.shift(); return rows.filter(r => r.length > 1).map(r => Object.fromEntries(h.map((k, i) => [k, r[i] || ""])));
}
const prop = Object.fromEntries(csv("report/metodo/campione-misura-v3-proposta.csv").map(r => [r.cig, r]));
const righe = csv("report/metodo/campione-misura-v3-cieco.csv").map(r => {
  const p = prop[r.cig] || {};
  return { cig: r.cig, cpv: r.cod_cpv, importo: Number(r.importo_lotto), ente: r.stazione_appaltante, aggiudicatari: r.aggiudicatari, testo: r.testo,
           regole_v31: { via: p.via, provider: p.provider, giurisdizione: p.giurisdizione, servizio: p.servizio } };
});
const N = 20;
for (let i = 0; i < righe.length; i += N)
  fs.writeFileSync(path.join(R, `report/metodo/llm/lotti/lotto-${String(i / N + 1).padStart(2, "0")}.jsonl`), righe.slice(i, i + N).map(x => JSON.stringify(x)).join("\n") + "\n");
console.log(righe.length, "contratti in", Math.ceil(righe.length / N), "lotti");
EOF
node tools/llm/prepara_lotti.js

