input.command:
node -e '
const fs=require("fs"),d="report/metodo/llm/";
const imp={};for(const f of fs.readdirSync(d+"lotti"))for(const l of fs.readFileSync(d+"lotti/"+f,"utf8").split("\n").filter(Boolean)){const j=JSON.parse(l);imp[j.cig]=j.importo}
const e=[];for(const f of fs.readdirSync(d+"esiti"))for(const l of fs.readFileSync(d+"esiti/"+f,"utf8").split("\n").filter(Boolean))e.push(JSON.parse(l));
const c={};e.forEach(x=>c[x.confidenza]=(c[x.confidenza]||0)+1);
const dubbi=e.filter(x=>x.confidenza!=="alta"||x.accordo_regole==="n");
const alta=e.filter(x=>x.confidenza==="alta"&&x.accordo_regole!=="n");
const M=a=>(a.reduce((s,x)=>s+(imp[x.cig]||0),0)/1e6).toFixed(0);
console.log("tot",e.length,c,"disaccordi",e.filter(x=>x.accordo_regole==="n").length);
console.log("dubbi",dubbi.length,M(dubbi)+"M; alta concordi",alta.length,M(alta)+"M");
'

