gh repo view mxmap-it/analisi-spesa-ict --json visibility -q .visibility; mkdir -p report/metodo/llm/giro2/lotti report/metodo/llm/giro2/esiti && node -e '
const fs=require("fs"),d="report/metodo/llm/";
const L={};for(const f of fs.readdirSync(d+"lotti"))for(const l of fs.readFileSync(d+"lotti/"+f,"utf8").split("\n").filter(Boolean)){const j=JSON.parse(l);L[j.cig]=j}
const e=[];for(const f of fs.readdirSync(d+"esiti"))for(const l of fs.readFileSync(d+"esiti/"+f,"utf8").split("\n").filter(Boolean))e.push(JSON.parse(l));
const dubbi=e.filter(x=>x.confidenza!=="alta"||x.accordo_regole==="n").map(x=>({...L[x.cig],giro1:{e_cloud:x.e_cloud,servizio:x.servizio,provider_prodotto:x.provider_prodotto,giurisdizione:x.giurisdizione,confidenza:x.confidenza,motivazione:x.motivazione}})).sort((a,b)=>b.importo-a.importo);
// campione di controllo: 1 ogni 10 delle alta concordi, scelta deterministica per CIG ordinato
const alta=e.filter(x=>x.confidenza==="alta"&&x.accordo_regole!=="n").map(x=>x.cig).sort().filter((_,i)=>i%10===0).map(c=>({...L[c],controllo:true}));
const tutti=dubbi.concat(alta);
for(let i=0;i<tutti.length;i+=5)fs.writeFileSync(d+`giro2/lotti/g2-${String(i/5+1).padStart(3,"0")}.jsonl`,tutti.slice(i,i+5).map(x=>JSON.stringify(x)).join("\n")+"\n");
console.log(dubbi.length,"dubbi +",alta.length,"controllo =",tutti.length,"in",Math.ceil(tutti.length/5),"pacchetti")'

